<script setup lang="ts">
import RecordSelect from '../components/RecordSelect.vue'
import {computed,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {post} from '../api/http'
import type {Order,Row} from '../api/types'
import {useMediaQuery} from '../composables/useMediaQuery'
import {useAuth} from '../stores/auth'
import {useResource,useMutation,money,number,dateTime,confirmAction,today} from '../composables/useResource'
import ExchangeActions from '../components/ExchangeActions.vue'
import RelatedRecords from '../components/RelatedRecords.vue'
import {usePagedResource} from '../composables/usePagedResource'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import StatusTag from '../components/StatusTag.vue'
import DataTable from '../components/DataTable.vue'
import MaterialReturnDialog from '../components/MaterialReturnDialog.vue'
import TracePanel from '../components/TracePanel.vue'
const route=useRoute(),router=useRouter(),auth=useAuth(),{data,loading,error,load}=useResource<Order|null>(()=>`/orders/${route.params.id}`,null)
const receiptList=usePagedResource(()=>auth.can('inventory:read')?`/records/receipts?order_id=${route.params.id}&id=${route.query.receipt_id||''}`:'')
async function reload(){await Promise.all([load(),receiptList.load()])}
const {saving,run}=useMutation(reload),dialog=ref(false),closureDialog=ref(false),closure=ref<'cancel'|'close'>('cancel'),reason=ref(''),reorderDialog=ref(false),requiredDate=ref(today()),reorderNote=ref('')
const tab=ref(String(route.query.tab||'items'))
const returnDialog=ref(false),selectedReceipt=ref<Row>(),isMobile=useMediaQuery()
const receipt=reactive<{warehouse_id:any;reference:string;note:string;items:{order_item_id:any;material_name:string;quantity:number;remaining:number;unit:string}[]}>({warehouse_id:'',reference:'',note:'',items:[]})
const receivable=computed(()=>['OPEN','PARTIAL'].includes(data.value?.status||'')&&auth.can('order:receive'))
const canReorder=computed(()=>auth.can('request:write')&&['CLOSED','CANCELLED'].includes(data.value?.status||'')&&!data.value?.replacement_request_id)
function openReceipt(){Object.assign(receipt,{warehouse_id:'',reference:'',note:'',items:data.value?.items.filter(i=>Number(i.remaining_quantity)>0).map(i=>({order_item_id:i.id,material_name:i.material_name,unit:i.unit,quantity:0,remaining:Number(i.remaining_quantity)}))||[]});dialog.value=true}
async function receive(){if(!receipt.warehouse_id||!receipt.reference.trim()){ElMessage.warning('请选择仓库并填写验收凭证号');return}const items=receipt.items.filter(i=>i.quantity>0);if(!items.length||items.some(i=>!Number.isFinite(i.quantity)||i.quantity>i.remaining)){ElMessage.warning('至少验收一项材料且数量不可超过待收数量');return}if(!await confirmAction('确认本次验收并入库？将同时更新库存及应付金额。'))return;if(await run(()=>post(`/orders/${route.params.id}/receive`,{warehouse_id:receipt.warehouse_id,reference:receipt.reference,note:receipt.note,items:items.map(i=>({order_item_id:i.order_item_id,quantity:i.quantity}))}),'验收入库成功'))dialog.value=false}
function openClosure(mode:typeof closure.value){closure.value=mode;reason.value='';closureDialog.value=true}
async function closeOrder(){if(!reason.value.trim()){ElMessage.warning('请填写原因');return}if(await run(()=>post(`/orders/${route.params.id}/${closure.value}`,{reason:reason.value}),closure.value==='cancel'?'订单已取消':'剩余采购已关闭，已入库应付保持不变'))closureDialog.value=false}
async function reorder(){if(!requiredDate.value){ElMessage.warning('请选择新需求日期');return}let draft:Row|undefined;if(await run(async()=>{draft=await post<Row>(`/orders/${route.params.id}/reorder-request`,{required_date:requiredDate.value,note:reorderNote.value})},'补采草稿已生成，请重新核实并提交审批')){reorderDialog.value=false;if(draft&&auth.can('request:read')&&auth.hasMenu('requests'))router.push(`/requests/${draft.id}`)}}
function openReturn(row:Row){selectedReceipt.value=row;returnDialog.value=true}
watch(()=>route.query.tab,v=>{tab.value=String(v||'items')})
</script>
<template>
<PageHeader :title="data?.code||'订单详情'" subtitle="跟踪收货、退货、剩余采购及退款，原始单据完整保留。" back="/orders"><ExchangeActions entity="orders" :print-id="String($route.params.id)" :filters="{id:$route.params.id}"/>
 <el-button @click="load" :loading="loading">刷新</el-button><el-button v-if="auth.can('order:write')&&data?.status==='OPEN'" type="danger" plain @click="openClosure('cancel')">取消订单</el-button><el-button v-if="auth.can('order:write')&&data?.status==='PARTIAL'" type="warning" plain @click="openClosure('close')">关闭剩余采购</el-button><el-button v-if="canReorder" plain type="primary" @click="reorderDialog=true">生成补采申请</el-button><el-button v-if="receivable" type="primary" @click="openReceipt">登记验收入库</el-button>
</PageHeader>
<ResourceState :error="error" :loading="loading" @retry="load"><template v-if="data">
 <div class="detail-banner"><div><StatusTag :value="data.status"/><h2>{{data.supplier_name}}</h2><p>{{data.project_name}} · 关联申请 {{data.request_code||data.request_id}}</p></div><div><span class="muted">原订单金额（元）</span><strong>{{money(data.total_amount)}}</strong></div></div>
 <el-alert v-if="data.close_reason" :title="`${data.status==='CLOSED'?'已关闭剩余采购':'订单已取消'}：${data.close_reason}`" :description="`关闭金额 ¥ ${money(data.closed_amount)} · ${dateTime(data.closed_at)}`" type="warning" :closable="false" show-icon class="mb"/>
 <el-alert v-if="data.replacement_request_id&&auth.can('request:read')&&auth.hasMenu('requests')" type="info" :closable="false" class="mb"><template #title>已生成补采申请 <el-button link type="primary" @click="$router.push(`/requests/${data.replacement_request_id}`)">查看新申请 #{{data.replacement_request_id}}</el-button>，需要独立审批。</template></el-alert>
 <div class="mini-metrics"><div><span>净采购订单额（元）</span><b>{{money(data.effective_amount)}}</b></div><div v-if="auth.can('finance:read')"><span>退货后应付（元）</span><b>{{money(data.payable?.amount)}}</b></div><div v-if="auth.can('finance:read')"><span>净实付（元）</span><b>{{money(data.payable?.paid_amount)}}</b></div><div v-if="auth.can('finance:read')"><span>{{Number(data.payable?.refundable_amount)>0?'待收供应商退款（元）':'应付未付（元）'}}</span><b>{{money(Number(data.payable?.refundable_amount)>0?data.payable?.refundable_amount:data.payable?.outstanding_amount)}}</b></div></div>
 <section class="panel"><el-descriptions :column="isMobile?1:2"><el-descriptions-item label="中选原因">{{data.selection_reason||'—'}}</el-descriptions-item><el-descriptions-item label="下单时间">{{dateTime(data.created_at)}}</el-descriptions-item></el-descriptions>
 <el-tabs v-model="tab">
 <el-tab-pane label="订单材料" name="items"><DataTable :rows="data.items" :search="false" :columns="[{key:'material_name',label:'材料名称'},{key:'specification',label:'规格型号'},{key:'unit',label:'单位',width:70},{key:'quantity',label:'原采购数量',number:true},{key:'received_quantity',label:'累计验收数量',number:true},{key:'returned_quantity',label:'已退货数量',number:true},{key:'closed_quantity',label:'已关闭数量',number:true},{key:'remaining_quantity',label:'剩余待收数量',number:true},{key:'unit_price',label:'单价（元）',money:true},{key:'amount',label:'原金额（元）',money:true}]"/></el-tab-pane>
 <el-tab-pane v-if="auth.can('inventory:read')" label="验收与退货" name="receipts"><p class="field-hint">退货关联原入库明细；原仓库存不足或存在冲突的付款申请时，服务端会拒绝入账。</p><DataTable :remote="receiptList.paging" @page="receiptList.onPage" @size="receiptList.onSize" @search="receiptList.onSearch" :rows="receiptList.data.value" :columns="[{key:'code',label:'入库单号'},{key:'warehouse_name',label:'验收仓库'},{key:'reference',label:'验收凭证'},{key:'amount',label:'原入库金额',money:true},{key:'created_at',label:'验收时间',date:true},{key:'operator_name',label:'经办人'}]"><template #actions="{row}"><ExchangeActions v-if="auth.can('inventory:read')" entity="receipts" :print-id="row.id" print-only/><el-button v-if="auth.can('order:receive')" link type="danger" :disabled="!row.items?.some((i:Row)=>Number(i.returnable_quantity)>0)" @click="openReturn(row)">办理采购退货</el-button></template></DataTable></el-tab-pane>
 <el-tab-pane label="退货记录" name="returns"><RelatedRecords entity="purchase-returns" :filters="{order_id:route.params.id,id:route.query.purchase_return_id}" :columns="[{key:'code',label:'退货单号'},{key:'reference',label:'退货凭证'},{key:'amount',label:'应付冲减（元）',money:true},{key:'stock_amount',label:'库存冲减（元）',money:true},{key:'variance_amount',label:'计价差额（元）',money:true},{key:'reason',label:'退货原因'},{key:'operator_name',label:'经办人'},{key:'created_at',label:'退货时间',date:true}]"/></el-tab-pane>
 <el-tab-pane v-if="auth.can('finance:read')" label="付款记录" name="payments"><RelatedRecords entity="payments" :filters="{order_id:route.params.id}" :columns="[{key:'reference',label:'付款凭证'},{key:'amount',label:'原付款金额',money:true},{key:'note',label:'说明'},{key:'operator_name',label:'经办人'},{key:'created_at',label:'付款时间',date:true}]"/></el-tab-pane>
 <el-tab-pane v-if="auth.can('finance:read')" label="退款记录" name="refunds"><RelatedRecords entity="supplier-refunds" :filters="{order_id:route.params.id}" :columns="[{key:'reference',label:'退款凭证'},{key:'amount',label:'收到退款（元）',money:true},{key:'note',label:'说明'},{key:'operator_name',label:'经办人'},{key:'created_at',label:'退款时间',date:true}]"/></el-tab-pane>
 <el-tab-pane label="全链路追溯" name="trace"><TracePanel v-if="tab==='trace'" kind="orders" :id="String(route.params.id)"/></el-tab-pane>
 </el-tabs></section>
</template></ResourceState>
<el-dialog v-model="dialog" title="部分 / 全部验收入库" width="880px" :close-on-click-modal="false"><el-alert title="只填写本次实际验收数量，未验收材料保留为待收。库存及应付由服务端入账。" type="info" :closable="false" show-icon class="mb"/><el-form label-position="top"><div class="form-grid"><el-form-item label="入库仓库 *"><RecordSelect v-model="receipt.warehouse_id" entity="warehouses"/></el-form-item><el-form-item label="验收凭证号 *"><el-input v-model="receipt.reference" maxlength="100" placeholder="实际验收单或送货单编号"/></el-form-item></div>
<div v-if="isMobile" class="mobile-form-lines"><section v-for="row in receipt.items" :key="row.order_item_id" class="mobile-form-line"><h3>{{row.material_name}}</h3><p class="field-hint">待收数量：{{number(row.remaining)}} {{row.unit}}</p><el-form-item label="本次验收数量"><el-input-number v-model="row.quantity" :min="0" :max="row.remaining" :precision="3" controls-position="right" style="width:100%"/></el-form-item></section></div><el-table v-else :data="receipt.items" border><el-table-column prop="material_name" label="材料名称"/><el-table-column label="待收数量"><template #default="{row}">{{number(row.remaining)}} {{row.unit}}</template></el-table-column><el-table-column label="本次验收数量" width="240"><template #default="{row}"><el-input-number v-model="row.quantity" :min="0" :max="row.remaining" :precision="3" controls-position="right"/></template></el-table-column></el-table><el-form-item label="验收说明" class="mt"><el-input v-model="receipt.note" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="receive">确认验收并入库</el-button></template></el-dialog>
<el-dialog v-model="closureDialog" :title="closure==='cancel'?'取消未收货订单':'关闭剩余采购'" width="560px" :close-on-click-modal="false"><el-alert title="保留原订单与已入库记录，停止未履行部分。后续如需采购，请重新提交补采申请。" type="info" :closable="false" class="mb"/><el-input v-model="reason" type="textarea" :rows="4" maxlength="1000" placeholder="填写取消或关闭原因"/><template #footer><el-button @click="closureDialog=false">返回</el-button><el-button type="danger" :loading="saving" @click="closeOrder">确认{{closure==='cancel'?'取消订单':'关闭剩余采购'}}</el-button></template></el-dialog>
<el-dialog v-model="reorderDialog" title="按未履行数量生成补采申请" width="560px" :close-on-click-modal="false"><el-alert title="每张关闭或取消订单只生成一次补采草稿，数量取未履行部分，需要重新审批。" type="info" :closable="false" class="mb"/><el-form label-position="top"><el-form-item label="新的需求日期"><el-date-picker v-model="requiredDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="补采说明"><el-input v-model="reorderNote" maxlength="850" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="reorderDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="reorder">生成草稿并重新审批</el-button></template></el-dialog>
<MaterialReturnDialog v-model="returnDialog" title="办理采购退货" :endpoint="`/receipts/${selectedReceipt?.id}/returns`" :items="selectedReceipt?.items||[]" hint="按原入库冲减应付，按当前库存计价减少库存；差额单独记录。已付款部分可能形成待收供应商退款。" @saved="reload"/>
</template>
